import { SITE_ORIGIN } from "@/lib/siteOrigin";

export const SITE_NAME = "Forest Circuit";
export const HOME_TITLE = "Forest Circuit | Methodist churches across Waltham Forest, Wanstead and Loughton";
export const SITE_DESCRIPTION =
  "Forest Methodist Circuit is a team ministry of ten churches across East London and Essex. Find a church, worship with us, and get involved in your community.";

/**
 * The circuit mark in white on brand green, drawn at 1200x630 — the size every
 * platform crops its preview from. Generated by scripts/build-share-image.ts;
 * regenerate it there rather than editing the PNG by hand.
 *
 * Absolute, because link-preview scrapers (WhatsApp, iMessage, Slack...)
 * fetch og:image as a standalone request.
 */
export const SHARE_IMAGE_URL = `${SITE_ORIGIN}/images/og-share.png`;

/**
 * The parts of the Open Graph block every page shares. Only these live in the
 * root layout: Next replaces openGraph wholesale rather than merging it, so a
 * title or url set there would be stamped onto every page that doesn't define
 * its own (which is how every inner page came to share as the home page). With
 * them left out, a shared link falls back to the page's own <title> and
 * address. Pages that set their own openGraph spread this in first so they
 * keep the image and site name.
 */
export const BASE_OPEN_GRAPH = {
  type: "website" as const,
  siteName: SITE_NAME,
  locale: "en_GB",
  images: [{ url: SHARE_IMAGE_URL, width: 1200, height: 630, alt: "Forest Methodist Circuit" }],
};
